const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');

// ── Background ──────────────────────────────────────────────

Given('the TodoMVC app is open', function () {
  // App is already loaded by world.js Before hook
  assert.ok(this.document, 'app should be loaded');
});

// ── Creation steps ──────────────────────────────────────────

When('I type {string} into the new-todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  // Dispatch an input event so the app can react if needed
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press Enter', function () {
  const input = this.document.querySelector('.new-todo');
  const event = new this.window.KeyboardEvent('keypress', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true,
  });
  input.dispatchEvent(event);
});

When('I create a todo named {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  const event = new this.window.KeyboardEvent('keypress', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true,
  });
  input.dispatchEvent(event);
});

Then('I should see a todo item labeled {string} in the list', function (label) {
  const items = this.document.querySelectorAll('.todo-list li');
  const found = Array.from(items).some(
    (li) => li.querySelector('label')?.textContent === label
  );
  assert.ok(found, `should find a todo labeled "${label}"`);
});

Then('the new-todo input should be cleared', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '', 'new-todo input should be empty');
});

Then('the todo list should be empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'todo list should be empty');
});

Then('the #main section should not be visible', function () {
  const main = this.document.querySelector('.main');
  const style = this.window.getComputedStyle(main);
  assert.strictEqual(style.display, 'none', '#main should be hidden');
});

Then('the #footer section should not be visible', function () {
  const footer = this.document.querySelector('.footer');
  const style = this.window.getComputedStyle(footer);
  assert.strictEqual(style.display, 'none', '#footer should be hidden');
});

Then('the #main section should be visible', function () {
  const main = this.document.querySelector('.main');
  const style = this.window.getComputedStyle(main);
  assert.notStrictEqual(style.display, 'none', '#main should be visible');
});

Then('the #footer section should be visible', function () {
  const footer = this.document.querySelector('.footer');
  const style = this.window.getComputedStyle(footer);
  assert.notStrictEqual(style.display, 'none', '#footer should be visible');
});

// ── Toggle steps ────────────────────────────────────────────

Given('I have the following todos:', function (table) {
  const titles = table.hashes().map((r) => r.title);
  for (const title of titles) {
    const input = this.document.querySelector('.new-todo');
    input.value = title;
    input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
    const event = new this.window.KeyboardEvent('keypress', {
      key: 'Enter',
      keyCode: 13,
      which: 13,
      bubbles: true,
    });
    input.dispatchEvent(event);
  }
});

Given('I have a todo named {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  const event = new this.window.KeyboardEvent('keypress', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true,
  });
  input.dispatchEvent(event);
});

Given('the todo {string} is completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = Array.from(items).find(
    (li) => li.querySelector('label')?.textContent === title
  );
  assert.ok(li, `todo "${title}" should exist`);
  const checkbox = li.querySelector('.toggle');
  checkbox.checked = true;
  li.classList.add('completed');
  checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

Given('all todos are completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const checkbox = li.querySelector('.toggle');
    checkbox.checked = true;
    li.classList.add('completed');
    checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  }
});

When('I click the toggle checkbox for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = Array.from(items).find(
    (li) => li.querySelector('label')?.textContent === title
  );
  assert.ok(li, `todo "${title}" should exist`);
  const checkbox = li.querySelector('.toggle');
  checkbox.click();
});

When('I click the toggle-all checkbox', function () {
  const checkbox = this.document.querySelector('#toggle-all');
  checkbox.click();
});

When('I click {string}', function (buttonText) {
  if (buttonText === 'Clear completed') {
    const btn = this.document.querySelector('.clear-completed');
    btn.click();
  }
});

Then('the todo {string} should have class {string}', function (title, cls) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = Array.from(items).find(
    (li) => li.querySelector('label')?.textContent === title
  );
  assert.ok(li, `todo "${title}" should exist`);
  assert.ok(li.classList.contains(cls), `todo "${title}" should have class "${cls}"`);
});

Then('the todo {string} should not have class {string}', function (title, cls) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = Array.from(items).find(
    (li) => li.querySelector('label')?.textContent === title
  );
  assert.ok(li, `todo "${title}" should exist`);
  assert.ok(!li.classList.contains(cls), `todo "${title}" should not have class "${cls}"`);
});

Then('the todo\'s checkbox should be checked', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  const checked = Array.from(items).every(
    (li) => li.querySelector('.toggle')?.checked
  );
  assert.ok(checked, 'all todo checkboxes should be checked');
});

Then('the todo\'s checkbox should not be checked', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  const unchecked = Array.from(items).every(
    (li) => !li.querySelector('.toggle')?.checked
  );
  assert.ok(unchecked, 'no todo checkbox should be checked');
});

Then('every todo should have class {string}', function (cls) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'there should be todos');
  const all = Array.from(items).every((li) => li.classList.contains(cls));
  assert.ok(all, `every todo should have class "${cls}"`);
});

Then('no todo should have class {string}', function (cls) {
  const items = this.document.querySelectorAll('.todo-list li');
  const none = Array.from(items).every((li) => !li.classList.contains(cls));
  assert.ok(none, `no todo should have class "${cls}"`);
});

Then('the toggle-all checkbox should be checked', function () {
  const checkbox = this.document.querySelector('#toggle-all');
  assert.ok(checkbox.checked, 'toggle-all should be checked');
});

Then('the toggle-all checkbox should not be checked', function () {
  const checkbox = this.document.querySelector('#toggle-all');
  assert.ok(!checkbox.checked, 'toggle-all should not be checked');
});

Then('I should see {int} todos in the list', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, `should see ${count} todos`);
});

Then('I should not see a todo named {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const found = Array.from(items).some(
    (li) => li.querySelector('label')?.textContent === title
  );
  assert.ok(!found, `should not see a todo labeled "${title}"`);
});

Then('the {string} button should not be visible', function (buttonText) {
  if (buttonText === 'Clear completed') {
    const btn = this.document.querySelector('.clear-completed');
    const style = this.window.getComputedStyle(btn);
    assert.strictEqual(style.display, 'none', 'Clear completed button should be hidden');
  }
});

// ── Editing steps ───────────────────────────────────────────

When('I double-click the label for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = Array.from(items).find(
    (li) => li.querySelector('label')?.textContent === title
  );
  assert.ok(li, `todo "${title}" should exist`);
  const label = li.querySelector('label');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

Then('the todo should have class {string}', function (cls) {
  const items = this.document.querySelectorAll('.todo-list li');
  // When editing, the li that has class "editing" is the one being edited
  const editing = Array.from(items).find((li) => li.classList.contains(cls));
  assert.ok(editing, `a todo should have class "${cls}"`);
});

Then('an edit input should be visible containing {string}', function (value) {
  const items = this.document.querySelectorAll('.todo-list li');
  const editing = Array.from(items).find((li) => li.classList.contains('editing'));
  assert.ok(editing, 'a todo should be in editing mode');
  const editInput = editing.querySelector('.edit');
  assert.ok(editInput, 'edit input should exist');
  assert.strictEqual(editInput.value, value, `edit input should contain "${value}"`);
});

When('I change the edit input value to {string}', function (value) {
  const items = this.document.querySelectorAll('.todo-list li');
  const editing = Array.from(items).find((li) => li.classList.contains('editing'));
  assert.ok(editing, 'a todo should be in editing mode');
  const editInput = editing.querySelector('.edit');
  editInput.value = value;
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I tab away \\(blur\\) from the edit input', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  const editing = Array.from(items).find((li) => li.classList.contains('editing'));
  assert.ok(editing, 'a todo should be in editing mode');
  const editInput = editing.querySelector('.edit');
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('I clear the edit input', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  const editing = Array.from(items).find((li) => li.classList.contains('editing'));
  assert.ok(editing, 'a todo should be in editing mode');
  const editInput = editing.querySelector('.edit');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press Escape', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  const editing = Array.from(items).find((li) => li.classList.contains('editing'));
  assert.ok(editing, 'a todo should be in editing mode');
  const editInput = editing.querySelector('.edit');
  const event = new this.window.KeyboardEvent('keydown', {
    key: 'Escape',
    keyCode: 27,
    which: 27,
    bubbles: true,
  });
  editInput.dispatchEvent(event);
});

When('I click the destroy button for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = Array.from(items).find(
    (li) => li.querySelector('label')?.textContent === title
  );
  assert.ok(li, `todo "${title}" should exist`);
  const destroyBtn = li.querySelector('.destroy');
  destroyBtn.click();
});

// ── Routing steps ───────────────────────────────────────────

Then('the todo-count should display {string}', function (count) {
  const strong = this.document.querySelector('.todo-count strong');
  assert.ok(strong, 'todo-count strong should exist');
  assert.strictEqual(strong.textContent, count, `todo-count should display "${count}"`);
});

Then('it should read {string} items left', function (text) {
  const countEl = this.document.querySelector('.todo-count');
  assert.ok(countEl, 'todo-count should exist');
  // Match text like "2 items left" or "1 item left"
  const match = countEl.textContent.match(/^\d+\s+items?\s+left$/);
  assert.ok(match, `todo-count should read something like "${text}"`);
  assert.strictEqual(countEl.textContent.trim(), text, 'todo-count text should match');
});

Then('it should read {string} item left', function (text) {
  const countEl = this.document.querySelector('.todo-count');
  assert.ok(countEl, 'todo-count should exist');
  assert.strictEqual(countEl.textContent.trim(), text, 'todo-count text should match');
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

Then('the filter link for {string} should have class {string}', function (filterName, cls) {
  const filters = this.document.querySelectorAll('.filters a');
  const link = Array.from(filters).find((a) => a.textContent.trim() === filterName);
  assert.ok(link, `filter link "${filterName}" should exist`);
  assert.ok(link.classList.contains(cls), `filter link "${filterName}" should have class "${cls}"`);
});

Then('the filter link for {string} should not have class {string}', function (filterName, cls) {
  const filters = this.document.querySelectorAll('.filters a');
  const link = Array.from(filters).find((a) => a.textContent.trim() === filterName);
  assert.ok(link, `filter link "${filterName}" should exist`);
  assert.ok(!link.classList.contains(cls), `filter link "${filterName}" should not have class "${cls}"`);
});

Given('I am viewing the Active filter', function () {
  this.navigate('#/active');
});

Then('the todo name should be {string}', function (name) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 1, 'should have exactly one todo');
  const label = items[0].querySelector('label');
  assert.ok(label, 'todo should have a label');
  assert.strictEqual(label.textContent, name, `todo name should be "${name}"`);
});

Then('I should not see a todo named {string} in the list', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const found = Array.from(items).some(
    (li) => li.querySelector('label')?.textContent === title
  );
  assert.ok(!found, `should not see "${title}" in the filtered list`);
});

// ── Persistence steps ───────────────────────────────────────

Then('localStorage should contain a key matching {string}', function (pattern) {
  const keys = Object.keys(this.localStorage);
  const matching = keys.filter((k) => k.match(new RegExp(pattern)));
  assert.ok(matching.length > 0, `localStorage should have a key matching "${pattern}"`);
  this._storageKey = matching[0];
});

Then('the stored value should include a todo with title {string}', function (title) {
  const key = this._storageKey;
  const data = JSON.parse(this.localStorage.getItem(key));
  const found = data.some((todo) => todo.title === title);
  assert.ok(found, `stored data should include a todo titled "${title}"`);
});

Then('the stored value for {string} should have completed set to true', function (title) {
  const key = this._storageKey || Object.keys(this.localStorage).find((k) => k.startsWith('todos-'));
  assert.ok(key, 'should have a todos storage key');
  const data = JSON.parse(this.localStorage.getItem(key));
  const todo = data.find((t) => t.title === title);
  assert.ok(todo, `todo "${title}" should exist in storage`);
  assert.strictEqual(todo.completed, true, `todo "${title}" should have completed: true`);
});

Then('the stored value for {string} should not have an {string} property', function (title, prop) {
  const key = this._storageKey || Object.keys(this.localStorage).find((k) => k.startsWith('todos-'));
  assert.ok(key, 'should have a todos storage key');
  const data = JSON.parse(this.localStorage.getItem(key));
  const todo = data.find((t) => t.title === title);
  assert.ok(todo, `todo "${title}" should exist in storage`);
  assert.strictEqual(todo[prop], undefined, `todo "${title}" should not have "${prop}" property`);
});

When('I reload the app', function () {
  // Re-load the app fresh in the same window context
  const storage = {};
  // Copy localStorage before reload
  for (let i = 0; i < this.window.localStorage.length; i++) {
    const k = this.window.localStorage.key(i);
    storage[k] = this.window.localStorage.getItem(k);
  }
  this.loadApp();
  // Restore localStorage
  for (const [k, v] of Object.entries(storage)) {
    this.window.localStorage.setItem(k, v);
  }
});

Then('each stored todo item should have an {string} property', function (prop) {
  const key = this._storageKey || Object.keys(this.localStorage).find((k) => k.startsWith('todos-'));
  assert.ok(key, 'should have a todos storage key');
  const data = JSON.parse(this.localStorage.getItem(key));
  for (const todo of data) {
    assert.ok(todo.hasOwnProperty(prop), `each stored todo should have "${prop}" property`);
  }
});

/* global STORAGE_KEY:readonly */
var STORAGE_KEY = 'todos-vanillajs';
var ENTER_KEY = 13;
var ESCAPE_KEY = 27;

var todos = [];
var filter = 'all';
var editingId = null;

// ── DOM refs ──────────────────────────────────────────────

var todoList = document.querySelector('.todo-list');
var newTodo = document.querySelector('.new-todo');
var main = document.querySelector('.main');
var footer = document.querySelector('.footer');
var todoCount = document.querySelector('.todo-count');
var clearCompleted = document.querySelector('.clear-completed');
var toggleAll = document.querySelector('#toggle-all');
var filters = document.querySelector('.filters');

// ── Storage ───────────────────────────────────────────────

function loadTodos() {
  try {
    var stored = localStorage.getItem(STORAGE_KEY);
    if (stored) { todos = JSON.parse(stored); } else { todos = []; }
  } catch (e) { todos = []; }
}

function saveTodos() {
  var data = todos.map(function (t) { return { id: t.id, title: t.title, completed: t.completed }; });
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
}

// ── Render ────────────────────────────────────────────────

function render() {
  var filtered = getFilteredTodos();
  renderList(filtered);
  renderFooter();
  renderMain();
  renderToggleAll();
  renderClearCompleted();
}

function getFilteredTodos() {
  if (filter === 'active') { return todos.filter(function (t) { return !t.completed; }); }
  if (filter === 'completed') { return todos.filter(function (t) { return t.completed; }); }
  return todos;
}

function renderList(filtered) {
  var html = '';
  for (var i = 0; i < filtered.length; i++) {
    var todo = filtered[i];
    var liClass = '';
    if (todo.completed) { liClass += 'completed'; }
    if (editingId === todo.id) { liClass += (liClass ? ' ' : '') + 'editing'; }
    html += '<li' + (liClass ? ' class="' + liClass + '"' : '') + ' data-id="' + todo.id + '">';
    html += '<div class="view">';
    html += '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>';
    html += '<label>' + escapeHtml(todo.title) + '</label>';
    html += '<button class="destroy"></button>';
    html += '</div>';
    html += '<input class="edit" value="' + escapeHtml(todo.title) + '">';
    html += '</li>';
  }
  todoList.innerHTML = html;

  // Re-bind events on rendered items
  var items = todoList.querySelectorAll('li');
  for (var j = 0; j < items.length; j++) { bindItemEvents(items[j]); }

  // Focus the edit input if editing
  if (editingId !== null) {
    var editInput = document.querySelector('.todo-list li.editing .edit');
    if (editInput) { editInput.focus(); }
  }
}

function escapeHtml(text) {
  var div = document.createElement('div');
  div.appendChild(document.createTextNode(text));
  return div.innerHTML;
}

function renderMain() { main.style.display = todos.length > 0 ? '' : 'none'; }
function renderFooter() { footer.style.display = todos.length > 0 ? '' : 'none'; }

function renderToggleAll() {
  var activeCount = todos.filter(function (t) { return !t.completed; }).length;
  toggleAll.checked = activeCount === 0 && todos.length > 0;
}

function renderClearCompleted() {
  var hasCompleted = todos.some(function (t) { return t.completed; });
  clearCompleted.style.display = hasCompleted ? '' : 'none';
}

function renderCount() {
  var activeCount = todos.filter(function (t) { return !t.completed; }).length;
  var word = activeCount === 1 ? 'item' : 'items';
  todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';
}

function renderFilterLinks() {
  var links = filters.querySelectorAll('a');
  for (var i = 0; i < links.length; i++) {
    var a = links[i];
    var href = a.getAttribute('href');
    var linkFilter = href.replace('#/', '') || 'all';
    if (linkFilter === filter) { a.classList.add('selected'); } else { a.classList.remove('selected'); }
  }
}

function renderFooter() { footer.style.display = todos.length > 0 ? '' : 'none'; }

// ── Item event binding ──────────────────────────────────────

function bindItemEvents(li) {
  var checkbox = li.querySelector('.toggle');
  var label = li.querySelector('label');
  var destroyBtn = li.querySelector('.destroy');
  var editInput = li.querySelector('.edit');

  checkbox.addEventListener('change', function () { toggleTodo(li.dataset.id); });
  label.addEventListener('dblclick', function () { startEditing(li.dataset.id); });
  destroyBtn.addEventListener('click', function () { destroyTodo(li.dataset.id); });
  editInput.addEventListener('blur', function () { finishEditing(li.dataset.id); });
  editInput.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) { finishEditing(li.dataset.id); }
    else if (e.keyCode === ESCAPE_KEY) { cancelEditing(li.dataset.id); }
  });
}

// ── Actions ────────────────────────────────────────────────

function createTodo(title) {
  var trimmed = title.trim();
  if (!trimmed) { return; }
  todos.push({
    id: Date.now() + Math.random(),
    title: trimmed,
    completed: false,
  });
  saveTodos();
  render();
  renderCount();
  renderFilterLinks();
}

function toggleTodo(id) {
  var todo = todos.find(function (t) { return t.id == id; });
  if (todo) {
    todo.completed = !todo.completed;
    saveTodos();
    render();
    renderCount();
    renderFilterLinks();
  }
}

function toggleAllTodos() {
  var activeCount = todos.filter(function (t) { return !t.completed; }).length;
  var allCompleted = activeCount === 0;
  for (var i = 0; i < todos.length; i++) { todos[i].completed = !allCompleted; }
  saveTodos();
  render();
  renderCount();
  renderFilterLinks();
}

function clearCompletedTodos() {
  todos = todos.filter(function (t) { return !t.completed; });
  saveTodos();
  render();
  renderCount();
  renderFilterLinks();
}

function destroyTodo(id) {
  todos = todos.filter(function (t) { return t.id != id; });
  if (editingId == id) { editingId = null; }
  saveTodos();
  render();
  renderCount();
  renderFilterLinks();
}

function startEditing(id) {
  editingId = id;
  render();
}

function finishEditing(id) {
  var editInput = document.querySelector('.todo-list li[data-id="' + id + '"] .edit');
  if (!editInput) { editingId = null; return; }
  var trimmed = editInput.value.trim();
  if (trimmed) {
    var todo = todos.find(function (t) { return t.id == id; });
    if (todo) { todo.title = trimmed; }
    saveTodos();
  } else {
    destroyTodo(id);
    editingId = null;
    saveTodos();
    render();
    renderCount();
    renderFilterLinks();
    return;
  }
  editingId = null;
  render();
  renderCount();
  renderFilterLinks();
}

function cancelEditing(id) {
  editingId = null;
  render();
}

// ── Routing ────────────────────────────────────────────────

function setFilter(newFilter) {
  filter = newFilter;
  render();
  renderCount();
  renderFilterLinks();
}

function handleHashChange() {
  var hash = window.location.hash.replace('#/', '') || 'all';
  setFilter(hash);
}

window.addEventListener('hashchange', handleHashChange);

// ── Event bindings (static elements) ────────────────────────

newTodo.addEventListener('keypress', function (e) {
  if (e.keyCode === ENTER_KEY) {
    createTodo(newTodo.value);
    newTodo.value = '';
  }
});

toggleAll.addEventListener('change', function () { toggleAllTodos(); });

clearCompleted.addEventListener('click', function () { clearCompletedTodos(); });

// ── Init ────────────────────────────────────────────────────

loadTodos();
handleHashChange();

