/* global STORAGE_KEY:readonly */
var STORAGE_KEY = 'todos-vanillajs';
var ENTER_KEY = 13;
var ESCAPE_KEY = 27;

var todos = [];
var filter = 'all';
var editingId = null;

// ── DOM refs ──────────────────────────────────────────────

var todoList = document.querySelector('.todo-list');
var newTodo = document.querySelector('.new-todo');
var main = document.querySelector('.main');
var footer = document.querySelector('.footer');
var todoCount = document.querySelector('.todo-count');
var clearCompleted = document.querySelector('.clear-completed');
var toggleAll = document.querySelector('#toggle-all');
var filters = document.querySelector('.filters');

// ── Storage ───────────────────────────────────────────────

function loadTodos() {
  try {
    var stored = localStorage.getItem(STORAGE_KEY);
    if (stored) { todos = JSON.parse(stored); } else { todos = []; }
  } catch (e) { todos = []; }
}

function saveTodos() {
  var data = todos.map(function (t) { return { id: t.id, title: t.title, completed: t.completed }; });
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
}

// ── Render ────────────────────────────────────────────────

function render() {
  var filtered = getFilteredTodos();
  renderList(filtered);
  renderFooter();
  renderMain();
  renderToggleAll();
  renderClearCompleted();
}

function getFilteredTodos() {
  if (filter === 'active') { return todos.filter(function (t) { return !t.completed; }); }
  if (filter === 'completed') { return todos.filter(function (t) { return t.completed; }); }
  return todos;
}

function renderList(filtered) {
  var html = '';
  for (var i = 0; i < filtered.length; i++) {
    var todo = filtered[i];
    var liClass = '';
    if (todo.completed) { liClass += 'completed'; }
    if (editingId === todo.id) { liClass += (liClass ? ' ' : '') + 'editing'; }
    html += '<li' + (liClass ? ' class="' + liClass + '"' : '') + ' data-id="' + todo.id + '">';
    html += '<div class="view">';
    html += '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>';
    html += '<label>' + escapeHtml(todo.title) + '</label>';
    html += '<button class="destroy"></button>';
    html += '</div>';
    html += '<input class="edit" value="' + escapeHtml(todo.title) + '">';
    html += '</li>';
  }
  todoList.innerHTML = html;

  // Re-bind events on rendered items
  var items = todoList.querySelectorAll('li');
  for (var j = 0; j < items.length; j++) { bindItemEvents(items[j]); }

  // Focus the edit input if editing
  if (editingId !== null) {
    var editInput = document.querySelector('.todo-list li.editing .edit');
    if (editInput) { editInput.focus(); }
  }
}

function escapeHtml(text) {
  var div = document.createElement('div');
  div.appendChild(document.createTextNode(text));
  return div.innerHTML;
}

function renderMain() { main.style.display = todos.length > 0 ? '' : 'none'; }
function renderFooter() { footer.style.display = todos.length > 0 ? '' : 'none'; }

function renderToggleAll() {
  var activeCount = todos.filter(function (t) { return !t.completed; }).length;
  toggleAll.checked = activeCount === 0 && todos.length > 0;
}

function renderClearCompleted() {
  var hasCompleted = todos.some(function (t) { return t.completed; });
  clearCompleted.style.display = hasCompleted ? '' : 'none';
}

function renderCount() {
  var activeCount = todos.filter(function (t) { return !t.completed; }).length;
  var word = activeCount === 1 ? 'item' : 'items';
  todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';
}

function renderFilterLinks() {
  var links = filters.querySelectorAll('a');
  for (var i = 0; i < links.length; i++) {
    var a = links[i];
    var href = a.getAttribute('href');
    var linkFilter = href.replace('#/', '') || 'all';
    if (linkFilter === filter) { a.classList.add('selected'); } else { a.classList.remove('selected'); }
  }
}

function renderFooter() { footer.style.display = todos.length > 0 ? '' : 'none'; }

// ── Item event binding ──────────────────────────────────────

function bindItemEvents(li) {
  var checkbox = li.querySelector('.toggle');
  var label = li.querySelector('label');
  var destroyBtn = li.querySelector('.destroy');
  var editInput = li.querySelector('.edit');

  checkbox.addEventListener('change', function () { toggleTodo(li.dataset.id); });
  label.addEventListener('dblclick', function () { startEditing(li.dataset.id); });
  destroyBtn.addEventListener('click', function () { destroyTodo(li.dataset.id); });
  editInput.addEventListener('blur', function () { finishEditing(li.dataset.id); });
  editInput.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) { finishEditing(li.dataset.id); }
    else if (e.keyCode === ESCAPE_KEY) { cancelEditing(li.dataset.id); }
  });
}

// ── Actions ────────────────────────────────────────────────

function createTodo(title) {
  var trimmed = title.trim();
  if (!trimmed) { return; }
  todos.push({
    id: Date.now() + Math.random(),
    title: trimmed,
    completed: false,
  });
  saveTodos();
  render();
  renderCount();
  renderFilterLinks();
}

function toggleTodo(id) {
  var todo = todos.find(function (t) { return t.id == id; });
  if (todo) {
    todo.completed = !todo.completed;
    saveTodos();
    render();
    renderCount();
    renderFilterLinks();
  }
}

function toggleAllTodos() {
  var activeCount = todos.filter(function (t) { return !t.completed; }).length;
  var allCompleted = activeCount === 0;
  for (var i = 0; i < todos.length; i++) { todos[i].completed = !allCompleted; }
  saveTodos();
  render();
  renderCount();
  renderFilterLinks();
}

function clearCompletedTodos() {
  todos = todos.filter(function (t) { return !t.completed; });
  saveTodos();
  render();
  renderCount();
  renderFilterLinks();
}

function destroyTodo(id) {
  todos = todos.filter(function (t) { return t.id != id; });
  if (editingId == id) { editingId = null; }
  saveTodos();
  render();
  renderCount();
  renderFilterLinks();
}

/** @planks("I double-click the label for {string}") */
function startEditing(id) {
  editingId = Number(id);
  render();
}

/** @planks("I change the edit input value to {string}") */
/** @planks("I tab away (blur) from the edit input") */
/** @planks("I clear the edit input") */
function finishEditing(id) {
  var editInput = document.querySelector('.todo-list li[data-id="' + id + '"] .edit');
  if (!editInput) { editingId = null; return; }
  var trimmed = editInput.value.trim();
  if (trimmed) {
    var todo = todos.find(function (t) { return t.id == id; });
    if (todo) { todo.title = trimmed; }
    saveTodos();
  } else {
    destroyTodo(id);
    editingId = null;
    saveTodos();
    render();
    renderCount();
    renderFilterLinks();
    return;
  }
  editingId = null;
  render();
  renderCount();
  renderFilterLinks();
}

/** @planks("I press Escape") */
function cancelEditing(id) {
  editingId = null;
  render();
}

// ── Routing ────────────────────────────────────────────────

function setFilter(newFilter) {
  filter = newFilter;
  render();
  renderCount();
  renderFilterLinks();
}

function handleHashChange() {
  var hash = window.location.hash.replace('#/', '') || 'all';
  setFilter(hash);
}

window.addEventListener('hashchange', handleHashChange);

// ── Event bindings (static elements) ────────────────────────

newTodo.addEventListener('keypress', function (e) {
  if (e.keyCode === ENTER_KEY) {
    createTodo(newTodo.value);
    newTodo.value = '';
  }
});

toggleAll.addEventListener('change', function () { toggleAllTodos(); });

clearCompleted.addEventListener('click', function () { clearCompletedTodos(); });

// ── Init ────────────────────────────────────────────────────

loadTodos();
handleHashChange();

